import numpy as np
els=[]; xyz=[]
for i,l in enumerate(open('final.xyz')):
    if i<2: continue
    p=l.split(); els.append(p[0]); xyz.append([float(p[1]),float(p[2]),float(p[3])])
xyz=np.array(xyz)
def d(i,j): return np.linalg.norm(xyz[i]-xyz[j])
def rot(p,axis,ang):
    axis=axis/np.linalg.norm(axis); a=np.radians(ang)
    return p*np.cos(a)+np.cross(axis,p)*np.sin(a)+axis*np.dot(axis,p)*(1-np.cos(a))
Cq=29
methyls={36:[38,39,40],37:[41,42,43]}
# all H indices
Hidx=[i for i in range(len(els)) if els[i]=='H']
for mc,hs in methyls.items():
    best=None; bestscore=-1
    for ang in range(0,360,5):
        newh=[rot(xyz[h]-xyz[mc], xyz[mc]-xyz[Cq], ang)+xyz[mc] for h in hs]
        # score: min distance from these H to any other H (excluding same methyl)
        score=1e9
        for nh in newh:
            for j in Hidx:
                if j in hs: continue
                score=min(score, np.linalg.norm(nh-xyz[j]))
        if score>bestscore: bestscore=score; best=ang
    # apply best rotation
    for h in hs:
        xyz[h]=rot(xyz[h]-xyz[mc], xyz[mc]-xyz[Cq], best)+xyz[mc]
    print(f'methyl {mc}: rotated {best} deg, min H-H now {bestscore:.3f}')
# also check CH2 groups clash
with open('answer.xyz','w') as f:
    f.write(f"{len(els)}\nCp3Ti macrocycle cation, S=1/2, charge +1\n")
    for el,p in zip(els,xyz): f.write(f"{el:2s} {p[0]:12.6f} {p[1]:12.6f} {p[2]:12.6f}\n")
# final clash report
bad=0
for i in range(len(els)):
    for j in range(i+1,len(els)):
        dd=d(i,j)
        if els[i]=='H' and els[j]=='H':
            if dd<1.6: bad+=1; print('H-H close',i,j,round(dd,2))
print('remaining H-H<1.6:',bad)
